{
  "name": "opencode-session-monitor",
  "version": "0.1.1",
  "type": "module",
  "description": "opencode 插件：TUI 侧边栏实时显示所有 session 的运行状态（busy/idle/error），支持鼠标 hover 高亮与点击切换，另附外部监控面板",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "session",
    "monitor",
    "sessions",
    "opencode-go"
  ],
  "license": "MIT",
  "main": "./dist/server.js",
  "exports": {
    ".": {
      "import": "./dist/server.js",
      "types": "./dist/server.d.ts"
    },
    "./server": {
      "import": "./dist/server.js",
      "types": "./dist/server.d.ts"
    },
    "./tui": {
      "import": "./dist/tui.js",
      "types": "./dist/tui.d.ts"
    }
  },
  "files": [
    "dist",
    "docs"
  ],
  "scripts": {
    "typecheck": "tsc --noEmit",
    "build": "tsc -p tsconfig.build.json",
    "deploy": "node scripts/deploy.mjs",
    "prepublishOnly": "npm run build"
  },
  "dependencies": {
    "@opencode-ai/plugin": "1.14.30"
  },
  "devDependencies": {
    "@opentui/core": "^0.2.16",
    "@opentui/solid": "^0.2.16",
    "@types/node": "^22.0.0",
    "typescript": "^5.8.0"
  }
}
